CREATE TABLE `workflows` (`id` CHAR(36) NOT NULL, `org_id` CHAR(36) NOT NULL, `owner_id` CHAR(36) NOT NULL, `name` VARCHAR(191) NOT NULL, `description` TEXT NULL, `status` ENUM('DRAFT','ACTIVE','INACTIVE') NOT NULL DEFAULT 'DRAFT', `mode` ENUM('MANUAL','AUTOMATIC') NOT NULL DEFAULT 'MANUAL', `resource_type` ENUM('FILE','FOLDER') NOT NULL, `trigger` VARCHAR(191) NOT NULL DEFAULT 'MANUAL', `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), INDEX `workflows_org_id_status_idx`(`org_id`,`status`), INDEX `workflows_org_id_owner_id_idx`(`org_id`,`owner_id`), CONSTRAINT `workflows_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `workflows_owner_id_fkey` FOREIGN KEY (`owner_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `workflow_states` (`id` CHAR(36) NOT NULL, `org_id` CHAR(36) NOT NULL, `workflow_id` CHAR(36) NOT NULL, `name` VARCHAR(191) NOT NULL, `position` INTEGER NOT NULL, `terminal` BOOLEAN NOT NULL DEFAULT false, PRIMARY KEY (`id`), UNIQUE INDEX `workflow_states_workflow_id_position_key`(`workflow_id`,`position`), INDEX `workflow_states_org_id_workflow_id_idx`(`org_id`,`workflow_id`), CONSTRAINT `workflow_states_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `workflow_states_workflow_id_fkey` FOREIGN KEY (`workflow_id`) REFERENCES `workflows`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `workflow_transitions` (`id` CHAR(36) NOT NULL, `org_id` CHAR(36) NOT NULL, `workflow_id` CHAR(36) NOT NULL, `from_state_id` CHAR(36) NOT NULL, `to_state_id` CHAR(36) NOT NULL, `name` VARCHAR(191) NOT NULL, `action` VARCHAR(191) NOT NULL DEFAULT 'APPROVE', PRIMARY KEY (`id`), INDEX `workflow_transitions_org_id_workflow_id_idx`(`org_id`,`workflow_id`), CONSTRAINT `workflow_transitions_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `workflow_transitions_workflow_id_fkey` FOREIGN KEY (`workflow_id`) REFERENCES `workflows`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `workflow_transitions_from_state_id_fkey` FOREIGN KEY (`from_state_id`) REFERENCES `workflow_states`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `workflow_transitions_to_state_id_fkey` FOREIGN KEY (`to_state_id`) REFERENCES `workflow_states`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `workflow_runs` (`id` CHAR(36) NOT NULL, `org_id` CHAR(36) NOT NULL, `workflow_id` CHAR(36) NOT NULL, `resource_type` ENUM('FILE','FOLDER') NOT NULL, `resource_id` CHAR(36) NOT NULL, `current_state_id` CHAR(36) NULL, `status` ENUM('RUNNING','WAITING','COMPLETED','REJECTED','FAILED') NOT NULL DEFAULT 'RUNNING', `started_by_id` CHAR(36) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `completed_at` DATETIME(3) NULL, PRIMARY KEY (`id`), INDEX `workflow_runs_org_id_workflow_id_created_at_idx`(`org_id`,`workflow_id`,`created_at`), INDEX `workflow_runs_org_id_resource_type_resource_id_idx`(`org_id`,`resource_type`,`resource_id`), CONSTRAINT `workflow_runs_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `workflow_runs_workflow_id_fkey` FOREIGN KEY (`workflow_id`) REFERENCES `workflows`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `workflow_runs_started_by_id_fkey` FOREIGN KEY (`started_by_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `workflow_runs_current_state_id_fkey` FOREIGN KEY (`current_state_id`) REFERENCES `workflow_states`(`id`) ON DELETE SET NULL ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `workflow_tasks` (`id` CHAR(36) NOT NULL, `org_id` CHAR(36) NOT NULL, `workflow_id` CHAR(36) NOT NULL, `run_id` CHAR(36) NOT NULL, `state_id` CHAR(36) NOT NULL, `assignee_id` CHAR(36) NOT NULL, `status` ENUM('PENDING','APPROVED','REJECTED','CANCELLED') NOT NULL DEFAULT 'PENDING', `due_at` DATETIME(3) NULL, `note` TEXT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `completed_at` DATETIME(3) NULL, PRIMARY KEY (`id`), INDEX `workflow_tasks_org_id_assignee_id_status_created_at_idx`(`org_id`,`assignee_id`,`status`,`created_at`), INDEX `workflow_tasks_org_id_workflow_id_idx`(`org_id`,`workflow_id`), CONSTRAINT `workflow_tasks_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `workflow_tasks_workflow_id_fkey` FOREIGN KEY (`workflow_id`) REFERENCES `workflows`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `workflow_tasks_run_id_fkey` FOREIGN KEY (`run_id`) REFERENCES `workflow_runs`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `workflow_tasks_state_id_fkey` FOREIGN KEY (`state_id`) REFERENCES `workflow_states`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `workflow_tasks_assignee_id_fkey` FOREIGN KEY (`assignee_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
